<?php
namespace App\Http\Controllers; use App\Models\{Empleado,EmployeeTrainingCredential,TrainingRequirement,TrainingTopic}; use App\Services\TrainingRequirementResolverService; use Illuminate\Http\Request; use Illuminate\Support\Facades\Storage; use Illuminate\Support\Str;
class TrainingRequirementController extends Controller{public function index(Request$r,TrainingRequirementResolverService$s){$company=$r->user()->company_id;$topics=TrainingTopic::availableTo($company)->get();$requirements=TrainingRequirement::forCompany($company)->with('topic')->get();$employees=Empleado::where('company_id',$company)->active()->when($r->area,fn($q,$v)=>$q->where('area_departamento',$v))->when($r->job,fn($q,$v)=>$q->where('cargo',$v))->get();$routes=$employees->mapWithKeys(fn($e)=>[$e->id=>$s->routeFor($e)]);return view('training.requirements.index',compact('topics','requirements','employees','routes'));}public function store(Request$r){$d=$r->validate(['training_topic_id'=>'required|exists:training_topics,id','requirement_type'=>'required|in:company,job,area,risk,employee,regulation,other','requirement_reference'=>'nullable|string|max:255','validity_months'=>'nullable|integer|min:1','requires_evaluation'=>'required|boolean','requires_certificate'=>'required|boolean','priority'=>'required|in:low,medium,high,critical','regulation_reference'=>'nullable|string|max:2000']);TrainingTopic::availableTo($r->user()->company_id)->findOrFail($d['training_topic_id']);TrainingRequirement::create(array_merge($d,['company_id'=>$r->user()->company_id,'required'=>true,'is_active'=>true,'created_by'=>$r->user()->id]));return back()->with('success','Requisito creado.');}public function externalCredential(Request$r){$d=$r->validate(['employee_id'=>'required|exists:empleados,id','training_topic_id'=>'nullable|exists:training_topics,id','credential_type'=>'required|in:external_certificate,regulated_certificate','name'=>'required|string|max:255','issuing_organization'=>'required|string|max:255','certificate_number'=>'nullable|string|max:255','issued_at'=>'required|date','expires_at'=>'nullable|date|after_or_equal:issued_at','verification_url'=>'nullable|url','file'=>'required|file|mimes:pdf,jpg,jpeg,png|max:10240']);$employee=Empleado::where('company_id',$r->user()->company_id)->findOrFail($d['employee_id']);$path=$r->file('file')->store('training/credentials/external',config('training.evidence_disk','local'));unset($d['file']);EmployeeTrainingCredential::create(array_merge($d,['company_id'=>$employee->company_id,'document_path'=>$path,'verification_code'=>hash('sha256',Str::random(48)),'status'=>'valid','created_by'=>$r->user()->id]));return back()->with('success','Certificado externo registrado en almacenamiento protegido.');}}
